describe('Send messages Tests', function () {
    beforeEach(function () {
        cy.intercept('POST', '/api/authenticate', function (req) {
            var urlParams = new URLSearchParams(req.body);
            var token = urlParams.get('token');
            if (token === 'valid-token') {
                req.reply({ status: 'ok', credentials: 'valid-token', language: 'en' });
            }
            else {
                req.reply({ status: 'error' });
            }
        });
        cy.visit('http://localhost:3000/auth');
        cy.get('.w-full.p-2.border-gray-300').first().type('KKA');
        cy.get('.flex > :nth-child(2) > .w-full').type('Salasana1!');
        cy.get('button[type="submit"]').click();
        cy.clearLocalStorage();
    });
    it("Should open the first receiver", function () {
        cy.get('.overflow-y-auto > :nth-child(1) > :nth-child(2) > .flex-col').click();
        cy.get('.m-2').type('Hello');
    });
    it("Set receiver to local storage ", function () {
        cy.window().then(function (window) {
            window.localStorage.setItem('receiver', '1001');
        });
        cy.wait(2000);
        cy.contains('Pääkäyttäjä');
    });
});
